SELECT

FROM RwaInstSpvProductAsset a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instInvestorId = #{instInvestorId}


    AND a.instSpvProductId = #{instSpvProductId}


    AND a.currency = #{currency}


    AND a.productAmount = #{productAmount}


    AND a.investorAmount = #{investorAmount}


    AND a.totalAmount = #{totalAmount}


    AND a.amount = #{amount}


    AND a.lastAmount = #{lastAmount}


    AND a.state = #{state}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM RwaInstSpvProductAsset a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instInvestorId = #{instInvestorId}


    AND a.instSpvProductId = #{instSpvProductId}


    AND a.currency LIKE CONCAT('%',#{currency}, '%')


    AND a.productAmount = #{productAmount}


    AND a.investorAmount = #{investorAmount}


    AND a.totalAmount = #{totalAmount}


    AND a.amount = #{amount}


    AND a.lastAmount = #{lastAmount}


    AND a.state = #{state}


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}
